        n = len(f)
        count = 0
        for i in range(n):
            if f[i] == 1:
                count += 1
        return count

    def minimal_brauer_rank(f):
        n = len(f)
        rank = 0
        for i in range(n):
            if f[i] == 1:
                rank += 1
        return rank

